/**
 * Research report — turns everything the research tools collected into a one-page summary:
 * numbers, a funnel, and findings ranked by impact, each with its evidence and the screen
 * (and element) it is about.
 *
 * Generated by fixed rules from the data, not by an AI model: the same data always gives
 * the same report, and every finding says what it is based on. Small samples are flagged.
 */
import { buildSessions, loadNotes, type Session } from '../insights/sessions'
import type { InsightEvent } from '../insights/store'
import { loadSessions, loadTests, summarize } from '../tests/store'
import { loadFiveSec, summarizeFiveSec } from '../fivesec/store'
import { doorStats, loadDoors } from '../doors/store'
import { loadGaze } from '../gaze/store'
import { APP, readJSON } from '../shared'
import type { PinNote } from '../pins/format'
import type { Impact, InsightSource } from '../repo/store'

export interface Finding {
  id: string
  title: string
  detail: string
  evidence: string
  impact: Impact
  source: InsightSource
  tags: string[]
  page?: string
  query?: string
  sel?: string
  /** a finding that confirms something works, rather than a problem */
  positive?: boolean
}

export interface FunnelStep { label: string; match: (p: string) => boolean; n: number }

export interface Report {
  generatedAt: string
  from?: string
  sessions: number
  participants: number
  medianMs: number
  numbers: { label: string; value: string; note?: string }[]
  funnel: FunnelStep[]
  findings: Finding[]
  tasks: { name: string; success: number; attempts: number; medianMs: number; firstRight: number; firstTotal: number }[]
  quotes: { text: string; who: string; where?: string }[]
  tagCounts: { tag: string; n: number }[]
  smallSample: boolean
}

export type Period = 'all' | '7d' | 'today'

const median = (a: number[]) => {
  if (!a.length) return 0
  const s = [...a].sort((x, y) => x - y)
  const m = Math.floor(s.length / 2)
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2
}
const pct = (n: number, d: number) => (d ? Math.round((n / d) * 100) : 0)
const secs = (ms: number) => (ms >= 60000 ? `${Math.floor(ms / 60000)} min ${Math.round((ms % 60000) / 1000)} s` : `${Math.round(ms / 1000)} s`)
const fid = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0, 60)
const of = (n: number, d: number) => `${n} of ${d}`

const FUNNEL: Omit<FunnelStep, 'n'>[] = [
  { label: 'Home', match: (p) => p === '/' },
  { label: 'Search or category', match: (p) => p === '/search' },
  { label: 'Product page', match: (p) => p.startsWith('/product/') },
  { label: 'Cart', match: (p) => p === '/cart' },
  { label: 'Checkout', match: (p) => p === '/checkout' },
  { label: 'Order placed', match: (p) => /^\/orders\/.+/.test(p) },
]

function sinceOf(period: Period): number {
  if (period === 'all') return 0
  const d = new Date()
  if (period === 'today') { d.setHours(0, 0, 0, 0); return d.getTime() }
  return d.getTime() - 7 * 24 * 3600 * 1000
}

export function buildReport(events: InsightEvent[], period: Period = 'all'): Report {
  const since = sinceOf(period)
  const inRange = (iso: string) => new Date(iso).getTime() >= since
  const sessions: Session[] = buildSessions(events.filter((e) => inRange(e.t)))
  const findings: Finding[] = []
  const add = (f: Omit<Finding, 'id'>) => findings.push({ ...f, id: fid(`${f.source}-${f.title}`) })

  /* ---------- sessions: funnel, problem taps, assistant use ---------- */
  const visited = (s: Session) => new Set(s.steps.filter((x) => x.kind === 'view').map((x) => x.page))
  const funnel: FunnelStep[] = FUNNEL.map((f) => ({ ...f, n: sessions.filter((s) => [...visited(s)].some(f.match)).length }))
  if (sessions.length >= 2) {
    let worst = { i: -1, drop: 0 }
    for (let i = 1; i < funnel.length; i++) {
      const prev = funnel[i - 1].n, now = funnel[i].n
      if (prev >= 2 && (prev - now) / prev > worst.drop) worst = { i, drop: (prev - now) / prev }
    }
    if (worst.i > 0 && worst.drop >= 0.4) {
      const a = funnel[worst.i - 1], b = funnel[worst.i]
      add({
        title: `Most people stop between ${a.label.toLowerCase()} and ${b.label.toLowerCase()}`,
        detail: `${of(b.n, a.n)} sessions that reached ${a.label.toLowerCase()} went on to ${b.label.toLowerCase()}. This is the biggest drop in the journey.`,
        evidence: `${pct(a.n - b.n, a.n)}% drop · ${sessions.length} sessions`, impact: worst.drop >= 0.6 ? 'high' : 'medium', source: 'sessions', tags: ['Navigation', 'Checkout'],
      })
    }
  }

  // Taps that did nothing, were rage taps, or landed on something that isn't a control.
  const bad = new Map<string, { page: string; query?: string; sel: string; label: string; n: number; rage: number; dead: number; sids: Set<string> }>()
  for (const s of sessions) for (const st of s.steps) {
    if (st.kind !== 'tap' || !st.flags.length || !st.sel) continue
    const key = `${st.page}|${st.sel}`
    const g = bad.get(key) ?? { page: st.page, query: st.query, sel: st.sel, label: st.label ?? '', n: 0, rage: 0, dead: 0, sids: new Set<string>() }
    g.n++
    if (st.flags.includes('rage')) g.rage++
    if (st.flags.includes('dead')) g.dead++
    g.sids.add(s.sid)
    bad.set(key, g)
  }
  ;[...bad.values()].filter((g) => g.n >= 2 || g.rage > 0).sort((a, b) => b.sids.size - a.sids.size || b.n - a.n).slice(0, 5).forEach((g) => {
    const name = g.label.replace(/^\(not a control\)\s*/, '').replace(/^Understood: /, 'Understood as · ')
    const isDead = g.dead >= g.n / 2
    add({
      title: isDead ? `People tap “${name}” on ${g.page}, but it isn’t clickable` : `“${name}” on ${g.page} often does nothing visible`,
      detail: isDead
        ? 'They expect it to do something (open, zoom, go somewhere). Make it work, or make it look less like a control.'
        : `Taps on it didn’t change the screen${g.rage ? `, and ${g.rage} were rage taps (3+ in a second)` : ''}. The control may be broken, slow, or its result not visible.`,
      evidence: `${g.n} tap${g.n === 1 ? '' : 's'} in ${g.sids.size} session${g.sids.size === 1 ? '' : 's'}`,
      impact: g.rage || g.sids.size >= 3 ? 'high' : 'medium', source: 'sessions', tags: [isDead ? 'Visual' : 'Bug'],
      page: g.page, query: g.query, sel: g.sel,
    })
  })

  const usedAssistant = sessions.filter((s) => s.steps.some((x) => x.kind === 'tap' && /ask ai|ask the assistant|refine with the assistant/i.test(x.label ?? ''))).length
  if (sessions.length >= 3) add({
    title: usedAssistant ? `${pct(usedAssistant, sessions.length)}% of sessions opened the shopping assistant` : 'Nobody opened the shopping assistant',
    detail: usedAssistant
      ? 'Compare with how many reached a product page: is the assistant a shortcut, or a last resort?'
      : 'The AI assistant may be hard to notice, or people don’t see why they’d need it.',
    evidence: `${of(usedAssistant, sessions.length)} sessions`, impact: usedAssistant ? 'low' : 'medium', source: 'sessions', tags: ['AI'], positive: usedAssistant > 0,
    page: '/', sel: '#ask-ai',
  })

  /* ---------- usability tests ---------- */
  const testSessions = loadSessions().filter((s) => inRange(s.startedAt))
  const tasks: Report['tasks'] = []
  for (const test of loadTests()) {
    const sum = summarize(test, testSessions)
    for (const t of sum.tasks) {
      if (!t.attempts) continue
      tasks.push({ name: t.task.prompt, success: t.success, attempts: t.attempts, medianMs: t.medianMs, firstRight: t.firstCorrect, firstTotal: t.firstTotal })
      const rate = t.success / t.attempts
      const firstWrong = t.firstTaps.find((f) => !f.correct)
      const where = t.task.success.kind === 'element' ? { page: t.task.success.page, sel: t.task.success.sel } : { page: t.task.startPage }
      if (rate < 0.7) add({
        title: `Only ${pct(t.success, t.attempts)}% completed: “${t.task.prompt}”`,
        detail: `${t.timeouts} ran out of time and ${t.gaveUp} gave up.${firstWrong ? ` The most common wrong first tap was “${firstWrong.label}”.` : ''}`,
        evidence: `${of(t.success, t.attempts)} participants · ${test.name}`, impact: rate < 0.5 ? 'high' : 'medium', source: 'usability', tags: ['Navigation'], ...where,
      })
      else if (t.medianMs > t.task.limitSec * 1000 * 0.6) add({
        title: `People manage “${t.task.prompt}”, but slowly`,
        detail: `Median time was ${secs(t.medianMs)} of the ${t.task.limitSec} s allowed.`,
        evidence: `${of(t.success, t.attempts)} succeeded · ${test.name}`, impact: 'medium', source: 'usability', tags: ['Navigation'], ...where,
      })
      else add({
        title: `“${t.task.prompt}” works well`,
        detail: `Median time ${secs(t.medianMs)}${t.firstTotal ? `; ${pct(t.firstCorrect, t.firstTotal)}% chose a good first tap` : ''}.`,
        evidence: `${of(t.success, t.attempts)} succeeded · ${test.name}`, impact: 'low', source: 'usability', tags: [], positive: true, ...where,
      })
    }
  }

  /* ---------- 5-second tests ---------- */
  for (const test of loadFiveSec()) {
    const s = summarizeFiveSec(test)
    if (!s.participants) continue
    const top = s.firsts[0]
    if (test.target) {
      const rate = s.hits / s.participants
      add({
        title: rate >= 0.6 ? `${pct(s.hits, s.participants)}% found “${test.target.label}” in five seconds` : `Only ${pct(s.hits, s.participants)}% went to “${test.target.label}” first`,
        detail: rate >= 0.6 ? `Asked: “${test.prompt}”` : `Asked: “${test.prompt}” Most clicked ${top && !top.hit ? `“${top.label}”` : 'elsewhere'} instead${s.participants - s.clicked ? `, and ${s.participants - s.clicked} didn’t click at all` : ''}.`,
        evidence: `${of(s.hits, s.participants)} participants · median ${(s.medianMs / 1000).toFixed(1)} s`, impact: rate >= 0.6 ? 'low' : rate < 0.4 ? 'high' : 'medium',
        source: 'fivesec', tags: ['Visual'], positive: rate >= 0.6, page: test.page, query: test.query, sel: test.target.sel,
      })
    }
  }

  /* ---------- fake doors ---------- */
  for (const d of loadDoors()) {
    const s = doorStats(d.id)
    if (s.seen < 3) continue
    add({
      title: `${pct(s.clickedBy, s.seen)}% of people who saw “${d.mode === 'new' ? d.label : d.anchorLabel}” tried it`,
      detail: `${d.name} ${s.rate >= 0.15 ? 'There’s interest worth following up.' : 'Interest looks low so far.'}`,
      evidence: `${of(s.clickedBy, s.seen)} people · ${s.clicks} clicks`, impact: s.rate >= 0.15 ? 'medium' : 'low', source: 'doors', tags: ['Opportunity'],
      positive: s.rate >= 0.15, page: d.page, sel: d.mode === 'existing' ? d.sel : `[data-fakedoor="${d.id}"]`,
    })
  }

  /* ---------- eye tracking ---------- */
  const gaze = loadGaze().filter((g) => inRange(g.t))
  const byPage = new Map<string, { n: number; below: number }>()
  gaze.forEach((g) => { const e = byPage.get(g.page) ?? { n: 0, below: 0 }; e.n++; if (g.y > g.vh) e.below++; byPage.set(g.page, e) })
  ;[...byPage.entries()].filter(([, e]) => e.n >= 60).forEach(([page, e]) => {
    const share = e.below / e.n
    if (share < 0.15) add({
      title: `On ${page}, attention stays above the fold`,
      detail: 'Content below the first screen was barely looked at. Move what matters up, or give a reason to scroll.',
      evidence: `${pct(e.below, e.n)}% of ${Math.round(e.n / 15)} s of gaze was below the first screen`, impact: 'low', source: 'gaze', tags: ['Visual'], page,
    })
  })

  /* ---------- researcher notes and comments ---------- */
  const notes = loadNotes()
  const inSessions = new Set(sessions.map((s) => s.sid))
  const tagCount = new Map<string, number>()
  const quotes: Report['quotes'] = []
  for (const [sid, n] of Object.entries(notes)) {
    if (!inSessions.has(sid)) continue
    n.tags.forEach((t) => tagCount.set(t, (tagCount.get(t) ?? 0) + 1))
    if (n.note.trim()) quotes.push({ text: n.note.trim(), who: 'Researcher note', where: `Session ${sessions.find((s) => s.sid === sid)?.n}` })
  }
  const tagCounts = [...tagCount.entries()].map(([tag, n]) => ({ tag, n })).sort((a, b) => b.n - a.n)
  const troubled = tagCounts.filter((t) => ['Confused', 'Got lost', 'Slow', 'Bug'].includes(t.tag))
  if (troubled.length && troubled[0].n >= 2) add({
    title: `Researchers tagged ${troubled.map((t) => `“${t.tag}” ${t.n}×`).join(', ')}`,
    detail: 'Read those sessions’ notes and replay them in Sessions.',
    evidence: `${tagCounts.reduce((a, t) => a + t.n, 0)} tags across ${Object.keys(notes).filter((s) => inSessions.has(s)).length} noted sessions`, impact: 'medium', source: 'notes', tags: [],
  })
  readJSON<PinNote[]>(`${APP}.reviewPins`, []).filter((c) => c.text.trim() && inRange(c.updatedAt)).slice(0, 6)
    .forEach((c) => quotes.push({ text: c.text.trim(), who: c.author ?? 'Reviewer', where: c.page }))

  /* ---------- order and headline numbers ---------- */
  const rank: Record<Impact, number> = { high: 0, medium: 1, low: 2 }
  findings.sort((a, b) => Number(!!a.positive) - Number(!!b.positive) || rank[a.impact] - rank[b.impact])
  const participants = sessions.length + new Set(testSessions.map((s) => s.id)).size
  const placed = funnel[funnel.length - 1].n
  return {
    generatedAt: new Date().toISOString(),
    from: since ? new Date(since).toISOString() : undefined,
    sessions: sessions.length,
    participants,
    medianMs: median(sessions.map((s) => s.ms)),
    numbers: [
      { label: 'Sessions', value: String(sessions.length), note: sessions.length ? `median ${secs(median(sessions.map((s) => s.ms)))}` : undefined },
      { label: 'Reached a product', value: `${pct(funnel[2].n, sessions.length)}%`, note: of(funnel[2].n, sessions.length) },
      { label: 'Placed an order', value: `${pct(placed, sessions.length)}%`, note: of(placed, sessions.length) },
      { label: 'Usability attempts', value: String(tasks.reduce((a, t) => a + t.attempts, 0)), note: `${tasks.length} task${tasks.length === 1 ? '' : 's'}` },
    ],
    funnel,
    findings,
    tasks,
    quotes,
    tagCounts,
    smallSample: participants < 5,
  }
}

export function reportMarkdown(r: Report, title: string) {
  const L = [`# ${title}`, '', `Generated ${new Date(r.generatedAt).toLocaleString('en-GB')} from the research tools. ${r.smallSample ? '**Small sample — treat as signals, not conclusions.**' : ''}`, '']
  L.push('## In numbers', '', ...r.numbers.map((n) => `- **${n.label}:** ${n.value}${n.note ? ` (${n.note})` : ''}`), '')
  L.push('## Journey', '', ...r.funnel.map((f) => `- ${f.label}: ${f.n}`), '')
  L.push('## Findings', '')
  r.findings.forEach((f, i) => L.push(`${i + 1}. **${f.title}** — ${f.impact}${f.positive ? ', works' : ''}`, `   ${f.detail}`, `   _Evidence: ${f.evidence}${f.page ? ` · ${f.page}` : ''}_`, ''))
  if (r.tasks.length) {
    L.push('## Usability tasks', '', '| Task | Success | Median time | Good first tap |', '|---|---|---|---|')
    r.tasks.forEach((t) => L.push(`| ${t.name} | ${t.success}/${t.attempts} | ${secs(t.medianMs)} | ${t.firstTotal ? `${t.firstRight}/${t.firstTotal}` : '—'} |`))
    L.push('')
  }
  if (r.quotes.length) { L.push('## In their words', ''); r.quotes.forEach((q) => L.push(`> ${q.text}`, `> — ${q.who}${q.where ? `, ${q.where}` : ''}`, '')) }
  return L.join('\n')
}
